// ⚙️ CONFIGURAÇÃO — edite APENAS os valores abaixo.
// Não guarde token aqui: o token do Telegram fica na credencial do n8n e o
// segredo do webhook na credencial de Header Auth.
const CONFIG = {
  // chat_id do Daniel (para receber os alertas). Descubra mandando /start
  // para o bot e abrindo https://api.telegram.org/bot<TOKEN>/getUpdates
  admin_chat_id: '',
  // canal público onde as ofertas são publicadas (ex: '@ofertaseletronics')
  canal: '@ofertaseletronics',
  // quantos minutos sem heartbeat até considerar o bot fora do ar
  limite_heartbeat_min: 30,
  // quantos erros na mesma janela até alertar
  limite_erros: 5,
};
return [{ json: { ...$json, CONFIG } }];

// Roteia o evento e prepara a mensagem de alerta (quando houver).
// Também acumula estatísticas do dia em workflow static data — é o que o
// relatório diário (workflow 04) e o watchdog abaixo consultam.
const e = $json.body ?? $json;
const CONFIG = $json.CONFIG ?? {};
const store = $getWorkflowStaticData('global');
const agora = Date.now();

store.contadores = store.contadores || {};
store.contadores[e.evento] = (store.contadores[e.evento] || 0) + 1;
store.ultimo_evento_ts = agora;

let alerta = '';
const d = e.dados || {};

switch (e.evento) {
  case 'heartbeat':
    // O pulso é o que sustenta o watchdog: sem ele, ninguém percebe que o
    // PC do Daniel desligou/travou — o próprio bot não teria como avisar.
    store.ultimo_heartbeat_ts = agora;
    store.ultimo_heartbeat = e.ts;
    store.heartbeat_dados = d;
    store.alerta_queda_enviado = false;
    break;

  case 'oferta_publicada':
    store.ofertas_hoje = (store.ofertas_hoje || 0) + 1;
    store.ultimas_ofertas = [{ titulo: d.titulo, preco: d.preco, desconto: d.desconto_pct,
                               link: d.link, foto: d.foto, ts: e.ts },
                             ...(store.ultimas_ofertas || [])].slice(0, 20);
    break;

  case 'produto_quarentena':
    alerta = `🚫 <b>Produto em quarentena</b>\n` +
             `${d.titulo || d.produto_id}\n` +
             `Falhou ${d.tentativas}x ao publicar — fora de rotação até ${(d.quarentena_ate||'').slice(0,16)}.\n` +
             `Motivo: ${d.mensagem || 'não informado'}`;
    break;

  case 'rodada_falhou':
    alerta = `⚠️ <b>Rodada falhou</b> (${d.fonte || '?'})\n<code>${(d.erro||'').slice(0,300)}</code>`;
    break;

  case 'rodada_pulada':
    // Rede fora do ar não é alerta imediato: o watchdog cobre a queda longa.
    store.ultima_rodada_pulada = e.ts;
    break;

  case 'rodada_concluida':
    store.ultima_rodada = { ts: e.ts, ...d };
    if ((d.erros || 0) >= (CONFIG.limite_erros ?? 5)) {
      alerta = `⚠️ <b>Rodada com ${d.erros} erro(s)</b>\n` +
               `Publicados: ${d.publicados} · Links falhos: ${d.links_falharam}`;
    }
    break;

  case 'erro':
    alerta = `❌ <b>Erro no bot</b>\n${(d.operacao||'')}: ${(d.mensagem||'').slice(0,300)}`;
    break;
}

// Sem admin_chat_id preenchido, o nó do Telegram falharia em TODA
// execução com "chat not found" — e, pior, em silêncio para quem não abre
// o histórico de execuções do n8n. Melhor não tentar mandar e deixar o
// motivo no output: quem instalou pelo n8n/setup_n8n.py já tem o campo
// preenchido; quem importou o JSON à mão vê aqui o que falta.
const temDestino = !!(CONFIG.admin_chat_id || '').toString().trim();
const config_incompleta = alerta !== '' && !temDestino;
if (config_incompleta) {
  console.log('ALERTA NÃO ENVIADO: preencha admin_chat_id no nó Configuração. ' +
              'Conteúdo: ' + alerta.replace(/<[^>]+>/g, ''));
}

return [{ json: { evento: e.evento, ts: e.ts, host: e.host, dados: d,
                  alerta, tem_alerta: alerta !== '' && temDestino,
                  config_incompleta,
                  chat_id: CONFIG.admin_chat_id, CONFIG } }];

// WATCHDOG — roda no n8n (nuvem), não no PC do Daniel. Se o bot parar de
// mandar heartbeat, é este nó que percebe. Um alerta gerado pelo próprio bot
// nunca chegaria justamente no caso que importa: o bot morto.
const store = $getWorkflowStaticData('global');
const CONFIG = { admin_chat_id: '' };   // preencha com o mesmo chat_id do nó Configuração
const LIMITE_MIN = 30;
const agora = Date.now();
const ultimo = store.ultimo_heartbeat_ts || 0;

if (!ultimo) {
  return [{ json: { alertar: false, chat_id: CONFIG.admin_chat_id, motivo: 'nenhum heartbeat recebido ainda' } }];
}

const idadeMin = Math.round((agora - ultimo) / 60000);

// Só alerta na TRANSIÇÃO para "fora do ar". Sem essa trava, o watchdog
// mandaria a mesma mensagem a cada 15 min durante toda a madrugada, e o
// alerta viraria ruído que ninguém lê.
const temDestino = !!(CONFIG.admin_chat_id || '').toString().trim();

if (idadeMin > LIMITE_MIN && !store.alerta_queda_enviado) {
  store.alerta_queda_enviado = true;
  const hb = store.heartbeat_dados || {};
  return [{ json: {
    alertar: temDestino,
    chat_id: CONFIG.admin_chat_id,
    idade_min: idadeMin,
    texto: `🔴 <b>Bot Ofertas parou de responder</b>\n` +
           `Último sinal há ${idadeMin} min (limite: ${LIMITE_MIN}).\n` +
           `Fila WhatsApp: ${hb.fila_whatsapp ?? '?'} · Quarentena: ${hb.quarentena ?? '?'}\n\n` +
           `Verifique o PC: o startup.py pode ter caído ou a máquina desligou.`,
  } }];
}

if (idadeMin <= LIMITE_MIN && store.alerta_queda_enviado === true) {
  store.alerta_queda_enviado = false;
  return [{ json: { alertar: true, chat_id: CONFIG.admin_chat_id, idade_min: idadeMin,
                    texto: `🟢 <b>Bot Ofertas voltou</b> — heartbeat normal de novo.` } }];
}

return [{ json: { alertar: false, chat_id: CONFIG.admin_chat_id, idade_min: idadeMin } }];
